1	/**
2	 * US Core FHIR R4 target, version 2 (builds on views v2): medications and laboratory results as FHIR resources.
3	 *
4	 * A second consumer of the same records: FHIR is one view, not the wire format. Which medications and
5	 * which results to emit, their statuses, the eGFR rule, the unit table and the time-scope rules are
6	 * exactly those of the app views in `views.d.ts` (read its module comment, `MedicationRow`,
7	 * `Analyte` and `LabResultRow` first). This file says how each one is written as FHIR.
8	 *
9	 * Why MedicationRequest and not MedicationStatement: US Core (3.1.1 through 7.0) profiles only
10	 * MedicationRequest for a patient's medications and represents medication-list entries, including
11	 * ones reported by the patient or copied from another organization, as MedicationRequest with
12	 * `reportedBoolean`. There is no US Core MedicationStatement profile, so a US Core client would not
13	 * read one.
14	 *
15	 * Only the elements below are used. Types are a subset of FHIR R4; property names and value sets are
16	 * FHIR's.
17	 */
18	
19	import type { FolioItem } from './views';
20	
21	export type { FolioItem };
22	
23	/** The mapper's entry point for this view set. `asOf` is a local date, `YYYY-MM-DD`. */
24	export type UsCoreTransform = (items: FolioItem[], asOf: string) => UsCoreRows;
25	
26	export interface UsCoreRows {
27	  /** One per row the app view would put in `medications`. */
28	  medicationRequests: MedicationRequest[];
29	  /** One per row the app view would put in `labs`. */
30	  observations: Observation[];
31	}
32	
33	export interface Coding { system: string; code: string; display?: string }
34	export interface CodeableConcept { coding?: Coding[]; text?: string }
35	export interface Reference { reference: string }
36	export interface Quantity {
37	  value: number;
38	  /** '<' | '<=' | '>=' | '>' when the printed result had a comparator. */
39	  comparator?: '<' | '<=' | '>=' | '>';
40	  /** Human-readable unit. */
41	  unit: string;
42	  /** Always "http://unitsofmeasure.org". */
43	  system: 'http://unitsofmeasure.org';
44	  /** UCUM code. For lab values: the unit from the `Analyte` table in views.d.ts (it is UCUM, except write "mL/min/{1.73_m2}" for eGFR and "mg/g" for UACR). */
45	  code: string;
46	}
47	
48	/** System URIs to use. */
49	export type KnownSystem =
50	  | 'http://www.nlm.nih.gov/research/umls/rxnorm'
51	  | 'http://loinc.org'
52	  | 'http://unitsofmeasure.org'
53	  | 'http://terminology.hl7.org/CodeSystem/observation-category';
54	
55	/**
56	 * US Core MedicationRequest (http://hl7.org/fhir/us/core/StructureDefinition/us-core-medicationrequest).
57	 */
58	export interface MedicationRequest {
59	  resourceType: 'MedicationRequest';
60	  /**
61	   * Deterministic id, unique within the output: letters, digits, '-' and '.', at most 64 characters
62	   * (e.g. built from the source's line id or the ingredient).
63	   */
64	  id: string;
65	  meta: { profile: ['http://hl7.org/fhir/us/core/StructureDefinition/us-core-medicationrequest'] };
66	  /**
67	   * From the app view's `MedicationRow.status`: 'active' -> 'active'; 'held' -> 'on-hold';
68	   * 'stopped' -> 'stopped'; 'unknown' -> 'unknown'.
69	   */
70	  status: 'active' | 'on-hold' | 'stopped' | 'unknown';
71	  /**
72	   * Why it is held or stopped: `text` is the source's reason text; `coding` (optional) uses system
73	   * "urn:folio:stop-reason" with the app view's `stop_reason` code.
74	   */
75	  statusReason?: CodeableConcept;
76	  /** 'order' for a clinician's prescription or order; 'plan' for a line copied from another organization's record or a patient's own list. */
77	  intent: 'order' | 'plan';
78	  /**
79	   * True when this is a reported medication rather than an order made by the source organization
80	   * (a patient's own list, or a line copied from another organization). False otherwise.
81	   */
82	  reportedBoolean: boolean;
83	  /**
84	   * The drug. `text` is the source's display name. `coding` carries every RxNorm code the source gives
85	   * for this drug (system rxnorm), with the generic ingredient name (lower case, as in
86	   * `MedicationRow.ingredient`) as the `display` of an ingredient-level code if one is given. When the
87	   * source gives no RxNorm code, put the ingredient name in `text` after the display name, as
88	   * "<display name> (<ingredient>)" (omit the parenthesis if the ingredient is unknown).
89	   */
90	  medicationCodeableConcept: CodeableConcept;
91	  /** "Patient/<item.patient>". */
92	  subject: Reference;
93	  /**
94	   * Who ordered it: required when `intent` is 'order' (US Core constraint us-core-21). Use the prescriber
95	   * the source names (`{ display: "<name>" }`, or `{ identifier: { system: "http://hl7.org/fhir/sid/us-npi", value: "<NPI>" } }`
96	   * when only an NPI is given); when the source names no prescriber, the issuing organization as `{ display: "<organization>" }`.
97	   */
98	  requester?: { display?: string; identifier?: { system: string; value: string } };
99	  /** The app view's `status_since` for 'active' rows when known, else the date the line or order began; a FHIR date or dateTime. Omit if unknown. */
100	  authoredOn?: string;
101	  /** At most one. `text` is the sig as written; `doseAndRate[0].doseQuantity` is the app view's `dose` (UCUM code "mg", "ug", "[iU]", "mL", or "{tbl}"). `timing.code.text` is the app view's `frequency` code. */
102	  dosageInstruction?: {
103	    text?: string;
104	    timing?: { code: { text: 'QD' | 'BID' | 'TID' | 'QHS' | 'QW' | 'PRN' | 'other' } };
105	    doseAndRate?: { doseQuantity: Quantity }[];
106	  }[];
107	}
108	
109	/**
110	 * US Core Laboratory Result Observation
111	 * (http://hl7.org/fhir/us/core/StructureDefinition/us-core-observation-lab).
112	 */
113	export interface Observation {
114	  resourceType: 'Observation';
115	  /** Deterministic id, unique within the output: letters, digits, '-' and '.', at most 64 characters. */
116	  id: string;
117	  meta: { profile: ['http://hl7.org/fhir/us/core/StructureDefinition/us-core-observation-lab'] };
118	  /** 'final' for final, amended or corrected values that stand; 'preliminary' otherwise. */
119	  status: 'final' | 'preliminary';
120	  /** Exactly [{ coding: [{ system: 'http://terminology.hl7.org/CodeSystem/observation-category', code: 'laboratory' }] }]. */
121	  category: [{ coding: [{ system: 'http://terminology.hl7.org/CodeSystem/observation-category'; code: 'laboratory'; display?: string }] }];
122	  /**
123	   * The test. `coding` must include a LOINC coding (system "http://loinc.org"): the source's LOINC
124	   * code when it gives one; when it gives none, the LOINC code for the analyte from this table
125	   * (2160-0 creatinine, 98979-8 eGFR CKD-EPI 2021, 2823-3 potassium, 2951-2 sodium, 2075-0 chloride,
126	   * 2028-9 bicarbonate, 33037-3 anion gap, 3094-0 BUN, 2345-7 glucose, 4548-4 A1c, 9318-7 UACR,
127	   * 777-3 platelets, 6690-2 WBC, 718-7 hemoglobin, 53060-9 beta-hydroxybutyrate, 2746-6 venous pH,
128	   * 2021-4 venous pCO2, 3040-3 lipase, 10839-9 troponin I, 2093-3 cholesterol, 2571-8 triglycerides,
129	   * 2085-9 HDL, 13457-7 LDL calculated). For an eGFR the source says was calculated with CKD-EPI 2009
130	   * but codes with an MDRD LOINC, keep the source's code. Also add the source's local code as a second
131	   * coding (system: any URI naming the source's code space, e.g. "urn:<issuer>:test-code").
132	   * `text` is the analyte name from the `Analyte` table (e.g. "egfr").
133	   */
134	  code: CodeableConcept;
135	  /** "Patient/<item.patient>". */
136	  subject: Reference;
137	  /** Specimen collection time, RFC 3339 with offset. */
138	  effectiveDateTime: string;
139	  /** The value in the analyte's unit (see `Quantity.code`). */
140	  valueQuantity: Quantity;
141	  /** For eGFR: the equation, as `{ text: 'ckd-epi-2021' | 'ckd-epi-2009' | 'mdrd' | 'unknown' }` (same rule as `LabResultRow.egfr_equation`). Omit for other analytes. */
142	  method?: { text: 'ckd-epi-2021' | 'ckd-epi-2009' | 'mdrd' | 'unknown' };
143	}
144

